<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue'
import {Link,Upload,Subtitles,Search,Play,ArrowLeft,Quote,Film,BookOpen,Network,Bookmark,Download,ExternalLink,RefreshCw,Settings2,X,ChevronRight} from 'lucide-vue-next'
import {api,useLearning} from '../useLearning.js'
import {requestId} from '../requestId.js'
import {authSession,requestLogin} from '../authState.js'
import {usePagination} from '../usePagination.js'
import RecordPagination from './ui/RecordPagination.vue'
import VideoMindmap from './VideoMindmap.vue'
const emit=defineEmits(['discuss'])
const {state,navigate,refresh,notify,openSession}=useLearning()
const inputMode=ref('link'),url=ref(''),title=ref(''),subtitleText=ref(''),file=ref(null),fileInput=ref(null),goal=ref(''),frames=ref(true),allowAsr=ref(false),optionsOpen=ref(false)
const list=ref([]),total=ref(0),page=ref(1),filter=ref(''),archived=ref(false),query=ref(''),loading=ref(false),error=ref(''),busy=ref(false),runtime=ref(null)
const selected=ref(null),tab=ref('summary'),segments=ref([]),segmentTotal=ref(0),segmentPage=ref(1),segmentQuery=ref(''),segmentBusy=ref(false),chosen=ref([]),selectedSegments=ref([]),player=ref(null),position=ref(0),jobsOpen=ref(false),notes=ref([]),generationChoice=ref(''),noteQuery=ref(''),replacement=ref('')
let disposed=false,version=0,detailVersion=0,segmentVersion=0,timer,debounce
const canUse=computed(()=>!authSession.login_required||authSession.authenticated)
const activeJob=computed(()=>selected.value?.job&&['queued','running'].includes(selected.value.job.state))
const retryLabel=computed(()=>selected.value?.job?.kind==='generate'?'重试生成总结与导图':selected.value?.segment_count?'补充关键画面':'读取字幕与画面')
const matchingGenerations=computed(()=>(selected.value?.generations||[]).filter(g=>g.source_version===selected.value?.subtitle_version))
const generation=computed(()=>matchingGenerations.value.find(g=>g.id===generationChoice.value)||matchingGenerations.value[0])
const data=computed(()=>generation.value?.data)
const displayedSections=computed(()=>(data.value?.sections||[]).filter(s=>!noteQuery.value||[s.title,s.body].join(' ').toLowerCase().includes(noteQuery.value.toLowerCase())))
const jobRows=computed(()=>selected.value?.jobs||[])
const {page:jobPage,items:pagedJobs}=usePagination(jobRows,()=>selected.value?.id)
const {page:notePage,items:pagedNotes}=usePagination(notes,()=>selected.value?.id)
const statusLabels={queued:'等待处理',running:'正在处理',metadata_ready:'待确认处理',ready:'字幕已就绪',completed:'已整理',partial:'部分完成',failed:'处理未完成',unknown:'处理已中断',cancelled:'已停止',uploaded:'文件已上传'}
const stageLabels={probe:'读取视频信息',subtitles:'读取平台字幕',download:'获取音视频',transcribe:'语音转写',frames:'提取关键画面',generate:'整理总结与导图'}
const clock=value=>{const seconds=Math.max(0,Math.floor(Number(value)||0));return Math.floor(seconds/60).toString().padStart(2,'0')+':'+(seconds%60).toString().padStart(2,'0')}
const duration=item=>item.duration?clock(item.duration):'时长待读取'
const storageKey=()=>`zhixing.video.${authSession.username||'local'}.${selected.value?.id}`
function persist(){if(selected.value)sessionStorage.setItem(storageKey(),JSON.stringify({position:position.value,tab:tab.value}))}
async function login(){try{await requestLogin();await load()}catch(e){error.value=e.message}}
async function load(){if(!canUse.value){list.value=[];total.value=0;return}const rev=++version;loading.value=true;try{const p=new URLSearchParams({query:query.value,status:filter.value,page:String(page.value),archived:String(archived.value)});const result=await api('/videos?'+p);if(disposed||rev!==version)return;list.value=result.items;total.value=result.total;error.value=''}catch(e){if(rev===version)error.value=e.message}finally{if(rev===version)loading.value=false}}
async function detail(){if(!selected.value?.id)return;const id=selected.value.id,rev=++detailVersion;try{const result=await api('/videos/'+id);if(disposed||rev!==detailVersion||selected.value?.id!==id)return;selected.value=result;notes.value=result.notes||[];if(!goal.value)goal.value=result.session_id||''}catch(e){if(rev===detailVersion)error.value=e.message}}
async function open(item){persist();selected.value=item;state.videoId=item.id;navigate('videos');error.value='';chosen.value=[];selectedSegments.value=[];segmentPage.value=1;segmentQuery.value='';generationChoice.value='';await detail();try{const saved=JSON.parse(sessionStorage.getItem(storageKey())||'{}');position.value=Number(saved.position)||0;tab.value=['summary','mindmap','illustrated','notes'].includes(saved.tab)?saved.tab:'summary'}catch{}await readSegments()}
function back(){persist();selected.value=null;state.videoId=null;navigate('videos');load()}
async function readSegments(){if(!selected.value?.id)return;const rev=++segmentVersion,id=selected.value.id;segmentBusy.value=true;try{const result=await api(`/videos/${id}/segments?`+new URLSearchParams({page:String(segmentPage.value),query:segmentQuery.value}));if(!disposed&&rev===segmentVersion&&selected.value?.id===id){segments.value=result.items;segmentTotal.value=result.total}}catch(e){if(rev===segmentVersion)error.value=e.message}finally{if(rev===segmentVersion)segmentBusy.value=false}}
const operationKeys=new Map()
async function action(path,body={},method='POST'){if(busy.value)return;busy.value=true;error.value='';const {request_id,...payload}=body;const signature=JSON.stringify([path,method,payload]);if(request_id){if(!operationKeys.has(signature))operationKeys.set(signature,request_id);body={...payload,request_id:operationKeys.get(signature)}}try{const result=await api(path,{method,body});operationKeys.delete(signature);return result}catch(e){error.value=e.message;return null}finally{busy.value=false}}
async function resolve(){const result=await action('/videos/resolve',{url:url.value,session_id:goal.value||null,request_id:requestId()});if(result)await open(result)}
async function importSubtitle(){const result=await action('/videos/imports',{title:title.value,text:subtitleText.value,source_url:url.value||'',session_id:goal.value||null,request_id:requestId()});if(result)await open(result)}
async function chooseFile(event){const chosenFile=event.target.files?.[0];if(!chosenFile)return;file.value=chosenFile;if(!title.value)title.value=chosenFile.name.replace(/\.[^.]+$/,'');if(/\.(srt|vtt|json)$/i.test(chosenFile.name)){inputMode.value='subtitle';subtitleText.value=await chosenFile.text()}}
async function upload(){if(!file.value||busy.value)return;busy.value=true;error.value='';try{if(!canUse.value)await requestLogin();if(file.value.size>(runtime.value?.max_upload_bytes||134217728))throw new Error('文件超过当前上传限制，请选择更小的视频或导入字幕。');const p=new URLSearchParams({filename:file.value.name,title:title.value,session_id:goal.value||''});const response=await fetch('/api/videos/uploads?'+p,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file.value});const result=await response.json();if(!response.ok)throw new Error(result.detail||'上传未完成，请重试。');await open(result)}catch(e){error.value=e.message}finally{busy.value=false}}
async function process(){const result=await action(`/videos/${selected.value.id}/process`,{request_id:requestId(),frames:frames.value,allow_asr:allowAsr.value});if(result){selected.value=result;await readSegments()}}
async function refreshPlatformSubtitles(){const result=await action(`/videos/${selected.value.id}/process`,{request_id:requestId(),frames:false,allow_asr:false,refresh_subtitles:true});if(result)selected.value=result}
async function generate(){const result=await action(`/videos/${selected.value.id}/generate`,{request_id:requestId()});if(result)selected.value=result}
async function cancel(){if(await action(`/videos/${selected.value.id}/cancel`))await detail()}
async function linkGoal(){if(await action(`/videos/${selected.value.id}/link`,{session_id:goal.value||null})){await detail();notify('学习目标关联已保存。')}}
async function archive(item,value=true){if(await action(`/videos/${item.id}/archive`,{archived:value})){if(selected.value?.id===item.id)back();await load();notify(value?'视频已归档，引用与资料保留。':'视频已恢复。')}}
async function quoteIds(ids){if(ids.length>50){ids=ids.slice(0,50);notify('本次显示前50条依据，可选择子节点缩小范围。')}chosen.value=ids;selectedSegments.value=[];if(!ids.length)return;try{const result=await api(`/videos/${selected.value.id}/segments?ids=`+encodeURIComponent(ids.join(',')));selectedSegments.value=result.items;const first=result.items[0];if(first)seek(first.start)}catch(e){error.value=e.message}}
function quoteSegment(segment){chosen.value=[segment.id];selectedSegments.value=[segment];seek(segment.start)}
function seek(seconds){position.value=seconds;if(player.value){player.value.currentTime=seconds;player.value.play().catch(()=>{})}persist()}
function videoLoaded(){if(player.value&&position.value)player.value.currentTime=position.value}
function retryStage(){if(selected.value?.job?.kind==='generate')return generate();return process()}
function nearestFrame(ids){const selectedIds=new Set(ids||[]);const frame=selected.value?.frames?.find(f=>f.segment_ids?.some(id=>selectedIds.has(id)));return frame||null}
async function save(kind='material',discuss=false){if(!selected.value)return;const result=await action(`/videos/${selected.value.id}/citations`,{segment_ids:chosen.value,generation_id:chosen.value.length?null:generation.value?.id||null,published:!discuss,kind,request_id:requestId()});if(result){await refresh();if(discuss===true){persist();emit('discuss',result)}else{await detail();notify(kind==='note'?'摘录已保存到灵感笔记。':'资料已保存到知识空间。')}}}
async function chooseReplacement(event){const f=event.target.files?.[0];if(f){if(f.size>500000){error.value='字幕文件超过50万字符限制。';return}replacement.value=await f.text()}}
async function replaceSubtitle(){const result=await action(`/videos/${selected.value.id}/subtitles`,{text:replacement.value,request_id:requestId()});if(result){selected.value=result;replacement.value='';chosen.value=[];selectedSegments.value=[];generationChoice.value='';segmentPage.value=1;await readSegments();notify('新字幕版本已保存，原始版本与旧引用保留。')}}
async function copyQuote(){try{await navigator.clipboard.writeText(selectedSegments.value.map(s=>`[${clock(s.start)}] ${s.text}`).join('\n'));notify('已复制所选片段。')}catch{error.value='复制未完成，可以直接选中原文复制。'}}
watch([query,filter,archived],()=>{page.value=1;clearTimeout(debounce);debounce=setTimeout(load,180)})
watch(page,load);watch(segmentPage,readSegments)
watch(segmentQuery,()=>{segmentPage.value=1;clearTimeout(debounce);debounce=setTimeout(readSegments,180)})
watch(tab,persist)
watch(canUse,async allowed=>{if(allowed){await load();runtime.value=await api('/videos/runtime').catch(()=>null);if(state.videoId)await open({id:state.videoId})}else{selected.value=null;list.value=[];notes.value=[];total.value=0}})
onMounted(async()=>{if(canUse.value){await load();runtime.value=await api('/videos/runtime').catch(()=>null);if(state.videoId)await open({id:state.videoId})}timer=setInterval(async()=>{if(document.hidden)return;if(selected.value){const before=selected.value.job?.state;if(activeJob.value){await detail();if(before!==selected.value?.job?.state)await readSegments()}}else if(list.value.some(v=>['queued','running'].includes(v.status)))load()},2300)})
onUnmounted(()=>{persist();disposed=true;++version;++detailVersion;++segmentVersion;clearInterval(timer);clearTimeout(debounce)})
const sectionPage=ref(1)
const sectionRows=computed(()=>displayedSections.value.slice((sectionPage.value-1)*3,sectionPage.value*3))
watch(()=>[generation.value?.id,noteQuery.value,tab.value],()=>sectionPage.value=1)
</script>

<template><section class="video-page">
 <template v-if="!selected">
  <header class="video-hero"><h1>视频研学</h1><p>把看过的视频，变成可以引用、讨论和实践的学习材料。</p></header>
  <section class="video-import"><h2>从一个视频开始</h2><div class="video-import-tabs" role="tablist" aria-label="导入方式"><button v-for="[value,label,glyph] in [['link','视频链接',Link],['upload','上传音视频',Upload],['subtitle','导入字幕',Subtitles]]" :key="value" role="tab" :aria-selected="inputMode===value" @click="inputMode=value"><component :is="glyph" :size="18"/>{{ label }}</button></div>
   <form v-if="inputMode==='link'" class="video-import-form" @submit.prevent="resolve"><label class="sr-only" for="video-url">视频链接</label><div class="video-url-field"><Link :size="20"/><input id="video-url" v-model="url" placeholder="粘贴视频链接，先查看标题与时长" maxlength="2000" autocomplete="off"></div><button class="primary-button" :disabled="busy||!url.trim()">{{ busy?'正在提交…':'解析链接' }}</button></form>
   <form v-else-if="inputMode==='upload'" class="video-upload-form" @submit.prevent="upload"><label class="video-drop"><Upload :size="25"/><span>{{ file?.name||'选择本地视频或音频文件' }}</span><small>MP4、MOV、MKV、WebM、MP3、WAV、M4A · 最大 {{ Math.round((runtime?.max_upload_bytes||134217728)/1048576) }}MB</small><input ref="fileInput" type="file" accept=".mp4,.mov,.mkv,.webm,.mp3,.wav,.m4a,.ogg" @change="chooseFile"></label><label>资料标题<input v-model="title" maxlength="150" required></label><button class="primary-button" :disabled="busy||!file||!title.trim()">{{ busy?'正在上传…':'上传并读取信息' }}</button></form>
   <form v-else class="video-subtitle-form" @submit.prevent="importSubtitle"><div><label>字幕文件<input type="file" accept=".srt,.vtt,.json" @change="chooseFile"></label><label>资料标题<input v-model="title" maxlength="150" required placeholder="给这份视频资料起个名字"></label></div><label>原字幕<textarea v-model="subtitleText" rows="4" maxlength="500000" required placeholder="选择 SRT／VTT 文件，或粘贴带时间戳的字幕…"></textarea></label><button class="primary-button" :disabled="busy||!title.trim()||!subtitleText.trim()">导入字幕</button></form>
   <p class="video-caption">优先读取平台字幕；读取受限时可选择转写或导入字幕。Bilibili、YouTube、抖音、快手链接按实际可访问情况解析。<button type="button" class="text-button" @click="inputMode='link';url='https://cs50.harvard.edu/python/shorts/functions/'">试读 Python 函数短课</button></p>
   <div class="video-import-footer"><label>关联学习目标<select v-model="goal"><option value="">稍后关联</option><option v-for="space in state.boot?.sessions||[]" :key="space.id" :value="space.id">{{ space.title }}</option></select></label><button class="text-button" @click="optionsOpen=!optionsOpen" :aria-expanded="optionsOpen"><Settings2 :size="17"/>处理选项</button></div><div v-if="optionsOpen" class="video-options"><label><input v-model="frames" type="checkbox">提取关键画面，生成图文阅读素材</label><label><input v-model="allowAsr" type="checkbox">平台字幕读取受限时，允许语音转写</label><small>先读取信息，再由你确认处理；总结与导图单独生成。</small></div>
  </section>
  <p v-if="error" class="inline-error" role="alert">{{ error }} <button class="text-button" @click="error=''">收起</button></p>
  <div class="video-library-layout"><section class="video-library"><div class="section-heading"><h2>我的视频</h2><label class="video-search"><Search :size="17"/><input v-model="query" aria-label="搜索视频资料" placeholder="搜索标题、字幕与笔记…"></label></div><div class="video-filter"><button v-for="[key,label] in [['','全部'],['completed','已整理'],['running','处理中'],['failed','需处理']]" :key="key" :aria-pressed="filter===key" :class="{active:filter===key}" @click="filter=key">{{ label }}</button><button class="text-button" @click="archived=!archived">{{ archived?'返回当前资料':'已归档' }}</button></div>
   <p v-if="loading" role="status">正在读取已保存的视频资料…</p><div v-else-if="!canUse" class="video-empty"><img src="/assets/video-learning/empty.webp" alt="胶片与书本"><h3>让视频，也成为你的学习资料。</h3><p>登录后导入视频，保存字幕、摘录和可以回看的来源。</p><button class="primary-button" @click="login">登录并开始</button></div>
   <div v-else-if="!list.length" class="video-empty"><img src="/assets/video-learning/empty.webp" alt="胶片与书本"><h3>{{ query?'没有匹配的视频资料':archived?'没有归档的视频':'从你真正想理解的视频开始。' }}</h3><p>粘贴一个链接，或带来自己的文件与字幕。</p></div>
   <article v-for="item in list" :key="item.id" class="video-library-row"><button class="video-thumbnail" :aria-label="'打开'+item.title" @click="open(item)"><img :src="item.poster_url||'/assets/video-learning/empty.webp'" alt="" loading="lazy"><span>{{ duration(item) }}</span></button><div><button class="video-row-title" @click="open(item)">{{ item.title }}</button><small>{{ item.platform_label }}{{ item.author?' · '+item.author:'' }} · {{ duration(item) }}</small><span class="video-state" :class="item.status">{{ statusLabels[item.status]||'待处理' }}</span></div><div class="video-row-actions"><button class="secondary-button" @click="open(item)">{{ ['queued','running'].includes(item.status)?'查看进度':'打开研学' }} <ChevronRight :size="16"/></button><button class="text-button" :disabled="busy" @click="archive(item,!archived)">{{ archived?'恢复':'归档' }}</button></div></article>
   <RecordPagination v-model="page" :total="total" :disabled="loading" label="视频资料"/>
  </section><aside class="video-guide"><h2>不止于一份总结</h2><ol><li><strong>选片段引用</strong><p>字幕、画面与时间点一起保留。</p></li><li><strong>带着资料问林知</strong><p>围绕具体原句，核查解释与依据。</p></li><li><strong>关联目标继续练习</strong><p>把看到的内容用于当前学习或项目。</p></li></ol><img src="/assets/video-learning/guide.webp" alt="山水与打开的书本"><p class="video-guide-note">资料不会自动变成掌握证据。</p></aside></div>
 </template>
 <template v-else>
  <header class="video-workspace-heading"><button class="text-button" @click="back"><ArrowLeft :size="17"/>返回视频库</button><div><h1>{{ selected.title||'正在读取视频…' }}</h1><p>{{ selected.platform_label }}{{ selected.author?' · '+selected.author:'' }} · {{ duration(selected) }} <span class="video-state" :class="selected.status">{{ statusLabels[selected.status] }}</span></p></div><div class="video-workspace-actions"><a v-if="selected.source_url" :href="selected.source_url" target="_blank" rel="noopener noreferrer" class="secondary-button"><ExternalLink :size="16"/>原视频</a><button class="text-button" @click="jobsOpen=!jobsOpen">处理记录</button></div></header>
  <p v-if="error" class="inline-error" role="alert">{{ error }}</p>
  <section v-if="activeJob||selected.job?.error||['metadata_ready','uploaded','unknown','cancelled'].includes(selected.status)" class="video-job-banner" :aria-busy="activeJob"><div><strong>{{ activeJob?(stageLabels[selected.job.stage]||'正在处理视频'):selected.job?.error?'本次处理没有完整完成':'准备好后，继续整理这份资料。' }}</strong><p>{{ selected.job?.error||selected.job?.message||'确认标题与时长后，读取字幕并按需提取画面。' }}</p><small v-if="activeJob">可以离开页面，任务与已完成的内容会保留。</small></div><button v-if="activeJob" class="secondary-button" :disabled="busy" @click="cancel">停止处理</button><button v-else class="primary-button" :disabled="busy" @click="retryStage">{{ retryLabel }}</button></section>
  <div class="video-workspace-grid"><section class="video-source-column"><div class="video-player"><video v-if="selected.media_url" ref="player" :src="selected.media_url" :poster="selected.poster_url" controls preload="metadata" @loadedmetadata="videoLoaded" @timeupdate="position=$event.target.currentTime" @pause="persist"/><iframe v-else-if="selected.embed_url" :src="selected.embed_url" title="原视频播放器" allow="fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen/><div v-else class="video-unplayable"><img :src="selected.poster_url||'/assets/video-learning/empty.webp'" alt="视频资料封面"><p>{{ selected.platform==='subtitle'?'这份资料只有字幕，可按时间阅读原文。':'原视频暂未取得可播放文件，可打开原站观看。' }}</p></div></div>
   <div class="video-source-meta"><span>{{ selected.transcript_label||'字幕尚未取得' }}</span><a v-if="selected.source_url" :href="selected.source_url+'#t='+Math.floor(position)" target="_blank" rel="noopener noreferrer">打开原视频 <ExternalLink :size="14"/></a></div>
   <section class="video-transcript"><header><h2>视频字幕</h2><label class="video-search"><Search :size="16"/><input v-model="segmentQuery" placeholder="搜索字幕…" aria-label="搜索视频字幕"></label></header><p v-if="segmentBusy" role="status">正在读取字幕…</p><div v-else class="video-segment-list"><article v-for="segment in segments" :key="segment.id" :class="{chosen:chosen.includes(segment.id)}"><button class="video-timestamp" :aria-label="'定位到'+clock(segment.start)" @click="seek(segment.start)">{{ clock(segment.start) }}</button><p>{{ segment.text }}</p><button class="video-quote" :aria-label="'引用'+clock(segment.start)+'字幕'" @click="quoteSegment(segment)"><Quote :size="17"/></button></article><p v-if="!segments.length" class="video-caption">{{ segmentQuery?'没有匹配的原句，可以换个关键词。':'取得字幕后，这里会显示带时间的原文。' }}</p></div><RecordPagination v-model="segmentPage" :total="segmentTotal" :disabled="segmentBusy" label="视频字幕"/></section>
   <section class="video-link-goal"><details><summary>导入／校订这份视频的字幕</summary><div class="video-options"><label>选择 SRT、VTT 或 JSON<input type="file" accept=".srt,.vtt,.json" @change="chooseReplacement"></label><textarea v-model="replacement" aria-label="新版本视频字幕" rows="3" maxlength="500000" placeholder="也可以粘贴带时间戳的字幕…"></textarea><small>保留原始版本和旧引用，新的总结需重新生成。</small><button class="secondary-button" :disabled="busy||activeJob||!replacement.trim()" @click="replaceSubtitle">保存新字幕版本</button></div></details><details><summary>处理选项</summary><div class="video-options"><label><input v-model="frames" type="checkbox">补充视频画面</label><label><input v-model="allowAsr" type="checkbox">平台字幕读取受限时，允许语音转写</label><button class="text-button" :disabled="busy||activeJob" @click="process">读取或补充资料</button><button v-if="selected.source_url" class="secondary-button" :disabled="busy||activeJob" @click="refreshPlatformSubtitles">重新读取平台字幕</button><small>优先匿名获取；失败时保留当前字幕与历史引用。</small></div></details><label>关联学习目标<select v-model="goal" @change="linkGoal"><option value="">不关联目标</option><option v-for="space in state.boot?.sessions||[]" :key="space.id" :value="space.id">{{ space.title }}</option></select></label><button v-if="selected.session_id" class="text-button" @click="openSession(selected.session_id)">用这个目标继续学习 <ChevronRight :size="15"/></button></section>
  </section>
  <section class="video-reading-column"><nav class="video-content-tabs" aria-label="视频整理内容"><button v-for="[key,label,glyph] in [['summary','总结',BookOpen],['mindmap','思维导图',Network],['illustrated','图文笔记',Film],['notes','我的摘录',Bookmark]]" :key="key" :class="{active:tab===key}" :aria-pressed="tab===key" @click="tab=key"><component :is="glyph" :size="17"/>{{ label }}</button></nav>
   <div class="video-reading-toolbar"><span v-if="generation">AI整理 · 第 {{ generation.revision }} 版</span><label v-if="generation" class="video-search"><Search :size="14"/><input v-model="noteQuery" aria-label="搜索本视频笔记" placeholder="搜索笔记…"></label><span v-else>保留原文，整理后再核对。</span><select v-if="matchingGenerations.length>1" v-model="generationChoice" aria-label="整理版本"><option v-for="g in matchingGenerations" :key="g.id" :value="g.id">第 {{ g.revision }} 版</option></select><button class="text-button" :disabled="busy||activeJob||!selected.segment_count" @click="generate"><RefreshCw :size="15"/>{{ generation?'重新整理':'生成总结与导图' }}</button><a v-if="selected.segment_count" :href="'/api/videos/'+selected.id+'/export?kind=srt'" class="text-button" download>SRT</a><a v-if="selected.segment_count" :href="'/api/videos/'+selected.id+'/export?kind=md&generation_id='+(generation?.id||'')" class="text-button" download><Download :size="15"/>导出</a><a v-if="selected.frames?.length" :href="'/api/videos/'+selected.id+'/export?kind=zip&amp;generation_id='+(generation?.id||'')" class="text-button" download>图文ZIP</a></div>
   <div v-if="tab==='notes'" class="video-notes"><article v-for="note in pagedNotes" :key="note.id"><h3>{{ note.title }}</h3><p>{{ note.text }}</p><small>{{ new Date(note.updated_at).toLocaleString('zh-CN') }}</small></article><p v-if="!notes.length">在左侧选择一段字幕，点击“保存摘录”，留下自己的阅读线索。</p><RecordPagination v-model="notePage" :total="notes.length" label="视频摘录"/></div>
   <VideoMindmap v-else-if="tab==='mindmap'&&data?.outline" :outline="data.outline" :sections="data.sections" @select="quoteIds"/>
   <div v-else-if="data" class="video-reading-document"><h2>{{ data.title||selected.title }}</h2><p v-if="tab==='summary'" class="video-summary-intro">{{ data.summary }}</p><article v-for="(section,index) in sectionRows" :key="index"><header><h3>{{ section.title }}</h3><button v-if="section.segment_ids?.length" class="video-timestamp" @click="quoteIds(section.segment_ids)"><Play :size="13"/>查看原句</button></header><figure v-if="tab==='illustrated'&&nearestFrame(section.segment_ids)"><img :src="nearestFrame(section.segment_ids).url" :alt="'视频原帧 '+clock(nearestFrame(section.segment_ids).time)" loading="lazy"><figcaption>视频原帧 · {{ clock(nearestFrame(section.segment_ids).time) }}</figcaption></figure><p>{{ section.body }}</p><button class="text-button" @click="quoteIds(section.segment_ids||[])"><Quote :size="15"/>引用这一段</button></article><RecordPagination v-model="sectionPage" :total="displayedSections.length" :page-size="3" label="视频章节笔记"/><p v-if="tab==='illustrated'&&!selected.frames?.length" class="video-caption">当前没有取得关键画面，保留文字笔记；可在处理选项中补充画面。</p></div>
   <div v-else class="video-empty video-reading-empty"><img src="/assets/video-learning/empty.webp" alt="胶片与书本"><h2>{{ selected.segment_count?'先看原文，再整理自己的理解。':'内容会从真实字幕开始。' }}</h2><p>{{ selected.segment_count?'可直接选片段引用，也可以生成总结、导图和图文笔记。':'完成字幕提取后，再开始总结与导图。识别失败时仍可导入字幕。' }}</p><button v-if="selected.segment_count" class="primary-button" :disabled="busy||activeJob" @click="generate">生成总结与导图</button><button v-else-if="!activeJob" class="secondary-button" :disabled="busy" @click="process">读取字幕与画面</button></div>
   <section v-if="chosen.length" class="video-selected-quote"><header><strong><Quote :size="17"/>当前引用 <span v-if="selectedSegments[0]">{{ clock(selectedSegments[0].start) }}—{{ clock(selectedSegments.at(-1).end) }}</span></strong><button aria-label="清除当前视频引用" @click="chosen=[];selectedSegments=[]"><X :size="17"/></button></header><p v-for="segment in selectedSegments" :key="segment.id"><span>{{ clock(segment.start) }} </span>{{ segment.text }}</p><button class="text-button" @click="copyQuote">复制原句</button><button class="text-button" :disabled="busy" @click="save('note')">保存摘录</button></section>
   <footer class="video-citation-actions"><small>{{ chosen.length?'引用所选片段，保留原句与时间。':'保存整份资料，保留视频与字幕来源。' }}</small><div><button class="secondary-button" :disabled="busy||!selected.segment_count" @click="save('material')"><Bookmark :size="17"/>保存到知识空间</button><button class="primary-button" :disabled="busy||!selected.segment_count" @click="save('material',true)"><Quote :size="17"/>带引用问林知</button></div></footer>
  </section></div>
  <section v-if="jobsOpen" class="video-job-history"><h2>处理记录</h2><article v-for="job in pagedJobs" :key="job.id"><strong>{{ stageLabels[job.kind]||'视频处理' }} · {{ ({queued:'排队中',running:'处理中',completed:'已完成',partial:'部分完成',failed:'未完成',unknown:'处理已中断',cancelled:'已停止'})[job.state] }}</strong><small>{{ new Date(job.created_at).toLocaleString('zh-CN') }}</small><p>{{ job.error||job.message }}</p></article><RecordPagination v-model="jobPage" :total="jobRows.length" label="视频处理记录"/></section>
 </template>
</section></template>
